import{D as e,E as t,P as n,t as r}from"./app-pxUgp8fi.js";var i=JSON.parse(`{"path":"/network/network/03-%E9%AB%98%E7%BA%A7.html","title":"网络基础·高级","lang":"zh-CN","frontmatter":{"title":"网络基础·高级","category":"网络设备","tags":["网络","华为","eNSP"],"description":"网络基础·高级 本篇面向能独立完成中小型网络设计与排障的运维同学，覆盖 OSPF 进阶、BGP、VRRP 高可用、MPLS/VPN 概念、网络监控运维（SNMP/NTP/日志）、LLDP 与网管平台、企业三层架构设计，以及软考网络工程师考点提示。全程华为 VRP 命令（华三 Comware 差异处用括号标注）。 1. OSPF 进阶 1.1 多区域 O...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"网络基础·高级\\",\\"image\\":[\\"\\"],\\"dateModified\\":\\"2026-10-13T01:50:03.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"LearnData\\",\\"url\\":\\"https://newzone.top\\"}]}"],["meta",{"property":"og:url","content":"https://newzone.top/LearnData/network/network/03-%E9%AB%98%E7%BA%A7.html"}],["meta",{"property":"og:site_name","content":"LearnData 开源笔记"}],["meta",{"property":"og:title","content":"网络基础·高级"}],["meta",{"property":"og:description","content":"网络基础·高级 本篇面向能独立完成中小型网络设计与排障的运维同学，覆盖 OSPF 进阶、BGP、VRRP 高可用、MPLS/VPN 概念、网络监控运维（SNMP/NTP/日志）、LLDP 与网管平台、企业三层架构设计，以及软考网络工程师考点提示。全程华为 VRP 命令（华三 Comware 差异处用括号标注）。 1. OSPF 进阶 1.1 多区域 O..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-13T01:50:03.000Z"}],["meta",{"property":"article:tag","content":"eNSP"}],["meta",{"property":"article:tag","content":"华为"}],["meta",{"property":"article:tag","content":"网络"}],["meta",{"property":"article:modified_time","content":"2026-10-13T01:50:03.000Z"}]]},"git":{"createdTime":1791856203000,"updatedTime":1791856203000,"contributors":[{"name":"lzj19970415","username":"lzj19970415","email":"lzj19970415@users.noreply.github.com","commits":1,"url":"https://github.com/lzj19970415"}]},"readingTime":{"minutes":18.36,"words":5507},"filePathRelative":"network/network/03-高级.md","excerpt":"\\n<p>本篇面向能独立完成中小型网络设计与排障的运维同学，覆盖 OSPF 进阶、BGP、VRRP 高可用、MPLS/VPN 概念、网络监控运维（SNMP/NTP/日志）、LLDP 与网管平台、企业三层架构设计，以及软考网络工程师考点提示。全程华为 VRP 命令（华三 Comware 差异处用括号标注）。</p>\\n<h2>1. OSPF 进阶</h2>\\n<h3>1.1 多区域 OSPF</h3>\\n<p>网络规模大时，单区域导致链路状态数据库（LSDB）庞大、SPF 计算频繁、收敛慢。多区域设计把网络按拓扑/功能分区，<strong>所有非骨干区域必须通过 Area 0（骨干）互联</strong>：</p>","autoDesc":true}`),a={name:`03-高级.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="网络基础·高级" tabindex="-1"><a class="header-anchor" href="#网络基础·高级"><span>网络基础·高级</span></a></h1><p>本篇面向能独立完成中小型网络设计与排障的运维同学，覆盖 OSPF 进阶、BGP、VRRP 高可用、MPLS/VPN 概念、网络监控运维（SNMP/NTP/日志）、LLDP 与网管平台、企业三层架构设计，以及软考网络工程师考点提示。全程华为 VRP 命令（华三 Comware 差异处用括号标注）。</p><h2 id="_1-ospf-进阶" tabindex="-1"><a class="header-anchor" href="#_1-ospf-进阶"><span>1. OSPF 进阶</span></a></h2><h3 id="_1-1-多区域-ospf" tabindex="-1"><a class="header-anchor" href="#_1-1-多区域-ospf"><span>1.1 多区域 OSPF</span></a></h3><p>网络规模大时，单区域导致链路状态数据库（LSDB）庞大、SPF 计算频繁、收敛慢。多区域设计把网络按拓扑/功能分区，<strong>所有非骨干区域必须通过 Area 0（骨干）互联</strong>：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>            Area 0 (骨干)</span></span>
<span class="line"><span> R1 ─── R2 ─── R3 ─── R4</span></span>
<span class="line"><span>        |           |</span></span>
<span class="line"><span>     Area 1      Area 2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：</p><table><thead><tr><th>概念</th><th>说明</th></tr></thead><tbody><tr><td>骨干区域</td><td>Area 0，所有流量必经，相当于&quot;高速公路主干道&quot;</td></tr><tr><td>普通区域</td><td>挂接在骨干区，区域内路由在内部汇总后通告</td></tr><tr><td>ABR</td><td>区域边界路由器（同时连骨干与普通区域）</td></tr><tr><td>ASBR</td><td>自治系统边界路由器（引入外部路由）</td></tr></tbody></table><p>配置要点：每台路由器只在相连区域里 <code>network</code> 宣告直连网段；ABR 同时进入多个 area。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># R2（ABR：同时连 Area0 与 Area1）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] ospf 1 router-id 2.2.2.2</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1] area 0</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.0] network 10.0.1.0 0.0.0.255</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.0] quit</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1] area 1</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.1] network 10.0.2.0 0.0.0.255</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.1] network 192.168.1.0 0.0.0.255</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三 Comware 命令完全一致（<code>ospf 1</code> / <code>area 1</code> / <code>network ...</code>）。</p></blockquote><h3 id="_1-2-区域类型-stub-区域" tabindex="-1"><a class="header-anchor" href="#_1-2-区域类型-stub-区域"><span>1.2 区域类型：Stub 区域</span></a></h3><p><strong>Stub 区域（末梢区域）</strong>：区域内没有 ASBR（不接受外部路由），区域内的路由器只需知道&quot;出去走 ABR&quot;，从而大幅缩减 LSDB。适用于<strong>只有一条出口的末端分支</strong>（如分公司、银行网点）。</p><p>在 ABR 上（Area 1 侧）宣告 Stub：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1] area 1</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.1] stub                    </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 区域 1 为 Stub</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>区域内所有路由器都要配置 <code>stub</code>（同一区域内必须统一宣告）。效果：区域 1 内不再传播外部路由（类型 5 LSA），由 ABR 自动下发默认路由。</p><blockquote><p>相关变种：Totally Stub（完全末梢，只保留默认路由，由 ABR 加 <code>stub no-summary</code>）。</p></blockquote><h3 id="_1-3-lsa-类型速查-软考高频" tabindex="-1"><a class="header-anchor" href="#_1-3-lsa-类型速查-软考高频"><span>1.3 LSA 类型速查（软考高频）</span></a></h3><p>OSPF 路由表里的 O 类路由其实来自不同类型的 LSA，软考选择题和案例常考：</p><table><thead><tr><th>类型</th><th>名称</th><th>产生者</th><th>说明</th></tr></thead><tbody><tr><td>1</td><td>Router LSA</td><td>每台路由器</td><td>本区域内的链路状态</td></tr><tr><td>2</td><td>Network LSA</td><td>DR</td><td>广播网的网段信息</td></tr><tr><td>3</td><td>Summary LSA</td><td>ABR</td><td>区域间路由摘要</td></tr><tr><td>4</td><td>ASBR Summary</td><td>ABR</td><td>到 ASBR 的路由</td></tr><tr><td>5</td><td>External LSA</td><td>ASBR</td><td>外部（其他协议引入）路由</td></tr></tbody></table><p>华为路由表中对应：<code>O</code> = 区内（1/2 类）、<code>O IA</code> = 区域间（3 类）、<code>O E2/O E1</code> = 外部（5 类）。</p><div class="language-vrp line-numbers-mode" data-highlighter="shiki" data-ext="vrp" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-vrp"><span class="line"><span>[Huawei] display ospf lsdb                     # 查看链路状态数据库</span></span>
<span class="line"><span>[Huawei] display ospf lsdb summary             # 只看 3 类摘要</span></span>
<span class="line"><span>[Huawei] display ospf routing                  # 查看 OSPF 路由及类型</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>软考点提示：路由类型 O / O IA / O E2 的含义与范围优先级（区内 &gt; 区域间 &gt; 外部）必须会辨析。</p></blockquote><h3 id="_1-4-dr-bdr-选举" tabindex="-1"><a class="header-anchor" href="#_1-4-dr-bdr-选举"><span>1.4 DR/BDR 选举</span></a></h3><p>在<strong>广播型网络（如以太网）</strong>，OSPF 路由器之间若两两建立邻接，邻居关系会爆炸（n 台路由器 n(n-1)/2 条）。于是选举 <strong>DR（指定路由器）与 BDR（备份指定路由器）</strong>，普通路由器（DRother）只和 DR/BDR 建邻接，DR 负责收集 LSA 后洪泛全网：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>选举规则：接口 DR 优先级（priority）大者优先，默认 1；相同则 Router-ID 大者胜。</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>查看与修改：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display ospf peer                          </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看邻居关系（含 DR/BDR 角色）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display ospf interface GigabitEthernet0/0/0</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-GigabitEthernet0/0/0] ospf dr-priority 100    </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 修改接口 DR 优先级</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>实际运维注意：DR/BDR 是<strong>选举出来的，与 router-id 大小相关</strong>，并<strong>不可抢占</strong>（新路由器加入不会改变现有 DR）。想让特定设备成为 DR，在组网规划时就应调高优先级。</p></blockquote><h3 id="_1-5-ospf-路由汇总" tabindex="-1"><a class="header-anchor" href="#_1-5-ospf-路由汇总"><span>1.5 OSPF 路由汇总</span></a></h3><p>汇总（聚合）把多条明细路由聚合成一条，<strong>减少 LSDB 与路由表规模、抑制路由震荡</strong>：</p><ul><li>区域间汇总：在 ABR 上做。</li><li>外部路由汇总：在 ASBR 上做。</li></ul><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 在 ABR 上把 Area 1 的多个网段汇总成 172.16.0.0/16 通告给 Area 0</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1] area 1</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1-area-0.0.0.1] abr-summary 172.16.0.0 255.255.0.0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三对应 <code>abr-summary 172.16.0.0 16</code>（后面直接写前缀长度）。</p></blockquote><h3 id="_1-6-下发默认路由" tabindex="-1"><a class="header-anchor" href="#_1-6-下发默认路由"><span>1.6 下发默认路由</span></a></h3><p>让内部网络&quot;统统走出口&quot;，在出口路由器（ASBR）上向 OSPF 域内下发默认路由：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-ospf-1] default-route-advertise always</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 不写 always 时，只有本地已有默认路由（如静态 0.0.0.0/0）才下发</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三为 <code>default-route-advertise</code> 相同（无 always 参数，默认行为是只要路由表有默认路由就下发）。</p></blockquote><p>验证：<code>display ospf routing</code> 应能看到 <code>O E2 0.0.0.0/0</code> 或 <code>O E2 10.0.0.0/8</code> 类路由。</p><h2 id="_2-bgp-基础" tabindex="-1"><a class="header-anchor" href="#_2-bgp-基础"><span>2. BGP 基础</span></a></h2><h3 id="_2-1-bgp-是什么" tabindex="-1"><a class="header-anchor" href="#_2-1-bgp-是什么"><span>2.1 BGP 是什么</span></a></h3><p>BGP（边界网关协议）是互联网/运营商之间交换路由的<strong>外部路由协议</strong>，基于 TCP 179 端口，专治&quot;路由数量巨大、拓扑关系复杂&quot;的场景。企业网涉及与运营商互联、专线对接时经常用到。<strong>AS（自治系统）</strong>：一个独立管理域，公网 AS 号由 ISP 分配，企业私网可用 64512~65535。</p><h3 id="_2-2-ebgp-与-ibgp" tabindex="-1"><a class="header-anchor" href="#_2-2-ebgp-与-ibgp"><span>2.2 EBGP 与 IBGP</span></a></h3><table><thead><tr><th>类型</th><th>邻居关系</th><th>典型场景</th></tr></thead><tbody><tr><td>EBGP</td><td>不同 AS 之间的邻居（直连物理口）</td><td>企业与运营商、运营商之间</td></tr><tr><td>IBGP</td><td>同一 AS 内部路由器</td><td>AS 内传递外部路由</td></tr></tbody></table><h3 id="_2-3-华为-bgp-配置示例" tabindex="-1"><a class="header-anchor" href="#_2-3-华为-bgp-配置示例"><span>2.3 华为 BGP 配置示例</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># R1（AS 65001）与 R2（AS 65002）直连，网段 10.0.0.0/24</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># R1 配置</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1] bgp 65001</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1-bgp] peer 10.0.0.2 as-number 65002        </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 指定邻居及其 AS</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1-bgp] ipv4-family unicast</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1-bgp-af-ipv4] peer 10.0.0.2 enable          </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 激活邻居（BGP 后续演进必配）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1-bgp-af-ipv4] network 192.168.1.0 255.255.255.0    </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 发布本地路由（network 是&quot;宣告&quot;，不是静态路由）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[R1-bgp-af-ipv4] quit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># R2 对称配置（AS 65002）</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">R2:</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> peer</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> 10.0.0.1</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> remote-as</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> 65000</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">R2:</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> network</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> 192.168.2.0</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> 255.255.255.0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>关键：BGP 的 <code>network</code> 命令是&quot;发布本地已存在的路由&quot;（直连/静态/OSPF 学到的），且必须匹配。华三命令几乎一致（<code>bgp 65001</code> / <code>peer 10.0.0.1 as-number 65000</code> / <code>network 192.168.2.0 24</code>）。</p></blockquote><h3 id="_2-4-查看-bgp-邻居" tabindex="-1"><a class="header-anchor" href="#_2-4-查看-bgp-邻居"><span>2.4 查看 BGP 邻居</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">R1#</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> display</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> bgp</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> peer</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">                    # 邻居状态：Established 表示建立成功</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">R1#</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> display</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> bgp</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> routing-table</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">           # BGP 路由表</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">R1#</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> display</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> bgp</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> peer</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> 10.0.0.2</span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;">           # 单个邻居详情</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>邻居建立状态机</strong>：Idle → Connect → OpenSent → OpenConfirm → <strong>Established</strong>。卡在 Idle 查：直连可达性、<code>remote-as</code> 是否正确、报文被 ACL 过滤；卡在 OpenConfirm 查：router-id 冲突、多协议不匹配。</p><h3 id="_2-5-bgp-路径属性与路由反射器-简述" tabindex="-1"><a class="header-anchor" href="#_2-5-bgp-路径属性与路由反射器-简述"><span>2.5 BGP 路径属性与路由反射器（简述）</span></a></h3><p>BGP 选路依赖<strong>路径属性（Path Attributes）</strong>，核心几个：</p><table><thead><tr><th>属性</th><th>作用</th></tr></thead><tbody><tr><td>AS-PATH</td><td>记录经过的 AS 序列，越长越不优（防环）</td></tr><tr><td>NEXT-HOP</td><td>下一跳地址（IBGP 学到后仍保持 EBGP 的 next-hop，需注意）</td></tr><tr><td>LOCAL-PREF</td><td>本地优先级，越高越优（AS 内出口选择）</td></tr><tr><td>MED</td><td>多出口度量，越小越优（AS 间）</td></tr></tbody></table><p><strong>IBGP 水平分割</strong>：从 IBGP 邻居学到的路由不再通告给其他 IBGP 邻居，导致 IBGP 需要全互联。<strong>路由反射器（RR）</strong>解决该问题：RR 反射收到的 IBGP 路由给客户端，避免全网全互联。</p><div class="language-vrp line-numbers-mode" data-highlighter="shiki" data-ext="vrp" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-vrp"><span class="line"><span>[R2] bgp 65001</span></span>
<span class="line"><span>[R2-bgp] peer 10.0.1.1 reflect-client      # 把邻居指定为路由反射器客户端</span></span>
<span class="line"><span>[R2-bgp] display bgp routing-table peer 10.0.1.1  # 查看该邻居收到的路由</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>软考层面，能说出属性名字和选路顺序即可（WEIGHT &gt; LOCAL_PREF &gt; AS_PATH &gt; MED &gt; IGP cost...）。华三命令 <code>peer 10.0.1.1 reflect-client</code> 相同。</p></blockquote><h2 id="_3-vrrp-高可用" tabindex="-1"><a class="header-anchor" href="#_3-vrrp-高可用"><span>3. VRRP 高可用</span></a></h2><h3 id="_3-1-虚拟网关原理" tabindex="-1"><a class="header-anchor" href="#_3-1-虚拟网关原理"><span>3.1 虚拟网关原理</span></a></h3><p>出口网关只有一台，挂了全网断网。<strong>VRRP（虚拟路由冗余协议）</strong>让多台路由器/三层交换机组成一个&quot;虚拟路由器&quot;（共享一个虚拟 IP 作为网关），正常情况下流量走 Master，Master 故障时 Backup 自动接管，切换对终端透明：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>虚拟网关 IP：192.168.10.254</span></span>
<span class="line"><span>+-------+          +-------+</span></span>
<span class="line"><span>| SW1(Master) |←— 主转发     |  SW2(Backup) |</span></span>
<span class="line"><span>+-------+          +-------+</span></span>
<span class="line"><span>   └────────── 终端网关 = 192.168.10.254 ──────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-2-华为-vrrp-配置示例" tabindex="-1"><a class="header-anchor" href="#_3-2-华为-vrrp-配置示例"><span>3.2 华为 VRRP 配置示例</span></a></h3><p>需求：SW1 为主网关（优先级高），SW2 备份，虚拟网关 192.168.10.254，VLAN 10 内终端网关填 192.168.10.254。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># SW1（Master）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] interface Vlanif 10</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] ip address 192.168.10.1 255.255.255.0</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] vrrp vrid 1 virtual-ip 192.168.10.254      </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 创建 VRRP 组，虚拟 IP 即终端网关</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] vrrp vrid 1 priority 120                 </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 提高优先级到 120（默认 100）&gt; Backup</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] vrrp vrid 1 preempt-mode timer delay 5   </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 抢占并延迟 5s（防频繁切换）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] quit</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># SW2（Backup，默认优先级 100 即可）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] interface Vlanif 10</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] ip address 192.168.10.2 255.255.255.0</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] vrrp vrid 1 virtual-ip 192.168.10.254</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-Vlanif10] quit</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>验证</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display vrrp                       </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看 Master/Backup 状态、虚拟 IP</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display vrrp brief</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>正常：SW1 为 <strong>Master</strong>，SW2 为 <strong>Backup</strong>；</li><li>拔掉 SW1 上联/停接口 → SW2 自动接管（约 3 秒），终端不掉线；</li><li>终端网关地址必须写<strong>虚拟 IP</strong>（192.168.10.254），不是物理接口 IP。</li></ul><blockquote><p>华三 Comware 的 VRRP 命令相同（<code>vrrp vrid 1 virtual-ip 192.168.10.254</code>），差异点：华三 VRRP 属于三层，配合 <code>interface Vlan-interface 10</code> 使用。</p></blockquote><h3 id="_3-3-vrrp-报文与认证-进阶了解" tabindex="-1"><a class="header-anchor" href="#_3-3-vrrp-报文与认证-进阶了解"><span>3.3 VRRP 报文与认证（进阶了解）</span></a></h3><p>VRRP 报文组播 224.0.0.18，可通过 <code>vrrp vrid 1 authentication-mode simple cipher</code> 开启简单认证，防止伪造。还可跟踪上行口/上行链路，使主设备下行链路断时自动降优先级交棒（配置较复杂，作为了解项）。</p><h3 id="_3-4-vrrp-双机负载分担-实战场景" tabindex="-1"><a class="header-anchor" href="#_3-4-vrrp-双机负载分担-实战场景"><span>3.4 VRRP 双机负载分担（实战场景）</span></a></h3><p>一台设备做主、另一台完全闲置浪费，生产中常用<strong>双组 VRRP 互相备份</strong>：VLAN10 以 SW1 为 Master、VLAN20 以 SW2 为 Master，两台设备都在转发流量：</p><div class="language-vrp line-numbers-mode" data-highlighter="shiki" data-ext="vrp" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-vrp"><span class="line"><span># SW1：VLAN10 主（优先级 120），VLAN20 备（默认 100）</span></span>
<span class="line"><span>[SW1] interface Vlanif 10</span></span>
<span class="line"><span>[SW1-Vlanif10] vrrp vrid 1 virtual-ip 192.168.10.254</span></span>
<span class="line"><span>[SW1-Vlanif10] vrrp vrid 1 priority 120</span></span>
<span class="line"><span>[SW1-Vlanif10] quit</span></span>
<span class="line"><span>[SW1] interface Vlanif 20</span></span>
<span class="line"><span>[SW1-Vlanif20] vrrp vrid 2 virtual-ip 192.168.20.254</span></span>
<span class="line"><span>[SW1-Vlanif20] quit</span></span>
<span class="line"><span></span></span>
<span class="line"><span># SW2：VLAN10 备，VLAN20 主</span></span>
<span class="line"><span>[SW2] interface Vlanif 10</span></span>
<span class="line"><span>[SW2-Vlanif10] vrrp vrid 1 virtual-ip 192.168.10.254</span></span>
<span class="line"><span>[SW2-Vlanif10] quit</span></span>
<span class="line"><span>[SW2] interface Vlanif 20</span></span>
<span class="line"><span>[SW2-Vlanif20] vrrp vrid 2 virtual-ip 192.168.20.254</span></span>
<span class="line"><span>[SW2-Vlanif20] vrrp vrid 2 priority 120</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>双机组网务必保证两台设备<strong>三层互联互通</strong>（中间跑 OSPF/静态路由），否则备用设备收到主设备的流量也无法转发。华三命令相同，接口名为 <code>Vlan-interface</code>。</p></blockquote><h3 id="_4-1-mpls-是什么" tabindex="-1"><a class="header-anchor" href="#_4-1-mpls-是什么"><span>4.1 MPLS 是什么</span></a></h3><p>MPLS（多协议标签交换）：传统 IP 转发每跳查路由表（长前缀匹配，慢）；MPLS 在入口给报文打<strong>标签</strong>，中间路由器只按标签快速交换，支持流量工程（TE）和 VPN。</p><p>在 L3VPN 中，华为运营商（SP）网络用 MPLS 承载客户私有路由：</p><ul><li><strong>CE</strong>（客户边缘设备）：客户侧路由器/防火墙，直连 PE；</li><li><strong>PE</strong>（运营商边缘设备）：接入客户，存放客户 VPN 路由；</li><li><strong>P</strong>（骨干设备）：只做标签转发，不感知 VPN 客户。</li></ul><div class="language- line-numbers-mode" data-highlighter="shiki" data-ext="" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-"><span class="line"><span>CE1 (客户A总部) ── PE1 ──(MPLS 骨干: P)── PE2 ── CE2 (客户A分部)</span></span>
<span class="line"><span>               └───── VPN-A 专线逻辑连接 ─────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_4-2-mpls-标签转发流程-了解" tabindex="-1"><a class="header-anchor" href="#_4-2-mpls-标签转发流程-了解"><span>4.2 MPLS 标签转发流程（了解）</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>CE1 发送普通 IP 报文 → PE1（入站 PE）</span></span>
<span class="line"><span>  ① PE1 查 VRF 路由表，压入两层标签（内层 VPN 标签 + 外层 LSP 标签）</span></span>
<span class="line"><span>  ② P 设备只看外层标签转发（不查 IP 路由表，速度更快）</span></span>
<span class="line"><span>  ③ PE2 弹出外层标签，按内层 VPN 标签识别 VPN 实例，转发给 CE2</span></span>
<span class="line"><span>  ④ CE2 收到的是普通 IP 报文，全程不感知 MPLS</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>核心术语速记：</p><table><thead><tr><th>术语</th><th>含义</th></tr></thead><tbody><tr><td>LSP</td><td>标签交换路径（标签经过的路径）</td></tr><tr><td>VRF / VPN-instance</td><td>每 VPN 独立的路由表，实现路由隔离</td></tr><tr><td>RD</td><td>路由区分符，解决不同客户同网段冲突</td></tr><tr><td>RT</td><td>路由目标，决定 VPN 路由向谁发布（导入/导出）</td></tr><tr><td>MP-BGP</td><td>扩展 BGP，在 PE 之间传递带标签的 VPN 路由</td></tr></tbody></table><blockquote><p>软考对 MPLS 主要考概念与 VPN 模型，不考复杂配置。能讲清 PE/P/CE 与&quot;客户路由隔离&quot;即可。</p></blockquote><h2 id="_5-网络监控与运维" tabindex="-1"><a class="header-anchor" href="#_5-网络监控与运维"><span>5. 网络监控与运维</span></a></h2><h3 id="_5-1-snmp-网络管理" tabindex="-1"><a class="header-anchor" href="#_5-1-snmp-网络管理"><span>5.1 SNMP 网络管理</span></a></h3><p>SNMP（简单网络管理协议）是网管系统（如华为 eSight、Zabbix、Prometheus 类）从设备采集状态/告警的标准协议，版本 v1/v2c（明文 community）/v3（加密认证）。</p><p><strong>华为设备开启 SNMP</strong>：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent                          </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 开启 SNMP 代理</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent sys-info version v2c     </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 使用 v2c 版本</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent community read cipher public123    </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 只读团体字（华三：snmp-agent community read public）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent sys-info contact </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">&quot;it@telecom&quot;</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent sys-info location </span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">&quot;Room-101&quot;</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 配置网管告警（Trap）上报：</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent trap enable</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] snmp-agent target-host trap address udp-domain 192.168.100.20 params securityname public v2c</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三差异：<code>snmp-agent sys-info version v2c</code>、<code>snmp-agent community read public</code> 语法一致；v3 配置 <code>snmp-agent group v3</code> / <code>snmp-agent usm-user v3</code>。</p></blockquote><p><strong>验证</strong>：<code>display snmp-agent</code>、<code>display snmp-agent community</code>，或在网管端 <code>snmpwalk</code> 测试。</p><h3 id="_5-2-ntp-时间同步" tabindex="-1"><a class="header-anchor" href="#_5-2-ntp-时间同步"><span>5.2 NTP 时间同步</span></a></h3><p>日志、证书、计费都依赖时钟，必须统一。设备向 NTP 服务器对时：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] ntp-service unicast-server 192.168.100.1          </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 指定 NTP 服务器</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] ntp-service source-interface Vlanif 100           </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 指定出接口（可选）</span></span>
<span class="line"><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display ntp status</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display ntp service unicast-server</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三 Comware：<code>ntp-service unicast-server 192.168.100.1</code>，完全相同。确认状态：<code>display ntp status</code> 中 <code>Clock Synchronized: yes</code>。</p></blockquote><h3 id="_5-3-日志管理-info-center" tabindex="-1"><a class="header-anchor" href="#_5-3-日志管理-info-center"><span>5.3 日志管理（info-center）</span></a></h3><p>把日志输出到 Console / 远程 syslog 服务器，方便集中审计：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] info-center enable                       </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 开启日志中心</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] info-center loghost 192.168.100.50       </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 发往远程 syslog（华三：info-center loghost 192.168.100.50）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] info-center timestamp log date            </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 日志时间戳格式</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display logbuffer                        </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看本地日志</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display alarm                            </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看告警</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>实践：云平台告警/运维平台统一采集交换机日志，便于事件关联分析。华为设备日志级别：Emergency 0 ~ Debugging 7，常规采集 info（6）以上。</p></blockquote><h2 id="_6-华为网络管理工具" tabindex="-1"><a class="header-anchor" href="#_6-华为网络管理工具"><span>6. 华为网络管理工具</span></a></h2><h3 id="_6-1-lldp-链路层发现协议" tabindex="-1"><a class="header-anchor" href="#_6-1-lldp-链路层发现协议"><span>6.1 LLDP 链路层发现协议</span></a></h3><p>LLDP 让交换机自动发现邻居设备及其能力（设备名、端口、VLAN 等），是网络可视化、自动拓扑的基础：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] lldp enable                          </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 全局开启（华三：lldp enable 相同）</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] interface GigabitEthernet0/0/1</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-GigabitEthernet0/0/1] lldp enable     </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 接口可选</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display lldp neighbor                </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 查看发现的邻居</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display lldp neighbor brief</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三为 <code>lldp enable</code> 与 <code>display lldp neighbor brief</code>（参数略有差异：<code>display lldp neighbor brief</code> 华三为 <code>display lldp neighbor-information</code>）。</p></blockquote><h3 id="_6-2-华为网管平台简述" tabindex="-1"><a class="header-anchor" href="#_6-2-华为网管平台简述"><span>6.2 华为网管平台简述</span></a></h3><ul><li><strong>eSight</strong>：华为统一网管（NMS），支持拓扑、告警、性能、配置备份，面向企业网/数据中心；</li><li><strong>iMaster NCE</strong>：下一代网络云化智能管理平台，面向 IP 网络（园区、广域、数据中心）；</li><li><strong>eNSP</strong> 模拟器本身配合 Wireshark 可抓包分析协议细节。</li></ul><blockquote><p>运维场景：设备上线后接入 eSight 统一监控，设置告警策略（CPU 超 80%、端口 down、掉线）自动通知值班。</p></blockquote><h2 id="_7-企业网络综合设计与排障" tabindex="-1"><a class="header-anchor" href="#_7-企业网络综合设计与排障"><span>7. 企业网络综合设计与排障</span></a></h2><h3 id="_7-1-三层架构-核心-汇聚-接入" tabindex="-1"><a class="header-anchor" href="#_7-1-三层架构-核心-汇聚-接入"><span>7.1 三层架构（核心 / 汇聚 / 接入）</span></a></h3><table><thead><tr><th>层次</th><th>设备</th><th>职责</th></tr></thead><tbody><tr><td>核心层</td><td>高端交换机/路由器</td><td>高速转发、路由、策略；不做复杂过滤</td></tr><tr><td>汇聚层</td><td>三层交换机</td><td>路由汇总、ACL、QoS、网关（VLANIF）</td></tr><tr><td>接入层</td><td>二层交换机</td><td>接入终端、端口安全、VLAN 划分</td></tr></tbody></table><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>核心层 SW1 ── SW2（双核心，VRRP/堆叠）</span></span>
<span class="line"><span>   │            │</span></span>
<span class="line"><span>汇聚层 S1 汇聚 S2（跑 OSPF/三层）</span></span>
<span class="line"><span>   │            │</span></span>
<span class="line"><span>接入层 A1 A2 A3（access 端口接终端）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>设计原则：核心冗余（双机 VRRP）、汇聚收敛（OSPF 多区域/汇总）、接入隔离（每个终端限速+端口安全）。政务云/运营商 IDC 网络基本沿用&quot;核心-汇聚-接入&quot;模式。</p><h3 id="_7-2-常见网络故障排查方法" tabindex="-1"><a class="header-anchor" href="#_7-2-常见网络故障排查方法"><span>7.2 常见网络故障排查方法</span></a></h3><p><strong>广播风暴</strong>：交换机 CPU 高、所有端口闪，单帧被反复转发成倍放大。排查：</p><ol><li><code>display mac-address</code> 观察 MAC 反复跳变端口；</li><li><code>display interface brief</code> 找收发包异常激增口；</li><li>逐段拔线定位环路，用 <code>shutdown</code> 隔离；</li><li>根因多为<strong>成环 + 未启用 STP（生成树协议）</strong>，或私接环路（网线回环）。</li></ol><p><strong>环路检测 loopback detection</strong>：华为交换机提供专门命令，自动检测接口环路并保护：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] interface GigabitEthernet0/0/1</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-GigabitEthernet0/0/1] loopback-detect enable      </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 开启环路检测</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-GigabitEthernet0/0/1] loopback-detect action shutdown   </span><span style="--shiki-light:#66707B;--shiki-dark:#BDC4CC;"># 检测到环路自动 down 口</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei-GigabitEthernet0/0/1] quit</span></span>
<span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">[Huawei] display loopback-detect detection-result</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三 Comware：<code>loopback-detection enable</code>（全局）+ 接口 <code>loopback-detection enable</code>，动作 <code>loopback-detection action shutdown</code>，等效于华为的 loopback-detect。</p></blockquote><h3 id="_7-3-stp-生成树协议基础-环路防护核心" tabindex="-1"><a class="header-anchor" href="#_7-3-stp-生成树协议基础-环路防护核心"><span>7.3 STP 生成树协议基础（环路防护核心）</span></a></h3><p>广播风暴的根因是<strong>二层环路 + 没有收敛机制</strong>。STP（生成树协议）自动把冗余链路中的一条设为阻塞（Block），逻辑上&quot;剪&quot;掉环路，链路故障时再快速恢复（重新计算）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-text"><span class="line"><span>        SW1</span></span>
<span class="line"><span>       /    \\</span></span>
<span class="line"><span>      /      \\</span></span>
<span class="line"><span>    SW2 ----- SW3     ← 物理成环，STP 阻塞其中一条，形成树形无环逻辑拓扑</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>选举过程</strong>：</p><ol><li>选根桥（Root Bridge）：交换机之间比较<strong>优先级（默认 32768）</strong>和 MAC，最小者当选；</li><li>每台非根交换机选根端口（Root Port，到根桥最短路径）；</li><li>每条链路选指定端口（Designated Port）；</li><li>其余端口进入 Blocking（阻塞）状态，不转发数据帧只收 BPDU。</li></ol><p><strong>端口状态</strong>：Disabled → Blocking → Listening → Learning → Forwarding（华为新版本为 Discarding/Learning/Forwarding）。</p><p><strong>华为设备启用与调整</strong>：</p><div class="language-vrp line-numbers-mode" data-highlighter="shiki" data-ext="vrp" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-vrp"><span class="line"><span>[Huawei] stp enable                          # 全局开启 STP（默认开启）</span></span>
<span class="line"><span>[Huawei] stp mode stp                      # 模式：STP / RSTP（默认）/ MSTP</span></span>
<span class="line"><span>[Huawei] stp priority 4096                 # 指定根桥（数值越小越优先，4096 常做核心）</span></span>
<span class="line"><span>[Huawei] display stp                        # 查看 STP 状态、根桥、端口角色</span></span>
<span class="line"><span>[Huawei] display stp interface GigabitEthernet0/0/1   # 查看单端口角色与状态</span></span>
<span class="line"><span>[Huawei] stp disable                        # 全局关闭（不推荐，需确保无环）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>华三 Comware：<code>stp enable</code>、<code>stp mode rstp</code>、<code>stp priority 4096</code> 一致；RSTP 收敛更快，生产推荐 RSTP/MSTP。</p></blockquote><p><strong>运维要点</strong>：</p><ul><li><strong>永远别裸奔</strong>（无 STP + 成环 = 全网瘫痪）；</li><li>交换机接终端的端口建议配 <code>stp edged-port enable</code>（边缘端口，接入后立即转发、不参与收敛，防止终端频繁插拔引发网络震荡）；</li><li>STP 收敛慢（默认 30~50 秒），RSTP/MSTP 收敛快（1~2 秒），核心网一般用 MSTP 多实例。</li></ul><p><strong>其他高频故障</strong>：</p><table><thead><tr><th>现象</th><th>排查命令/思路</th></tr></thead><tbody><tr><td>终端上不了网</td><td><code>display ip interface brief</code> 看接口状态，<code>display ip routing-table</code> 查路由，ping 网关</td></tr><tr><td>IP 冲突</td><td><code>display arp</code> 看异常重复记录，结合 DHCP 排除地址</td></tr><tr><td>网速慢</td><td><code>display interface</code> 看速率/双工、<code>display cpu-usage</code> 看 CPU 占用、链路利用率</td></tr><tr><td>端口频繁 flap</td><td>看 <code>display interface</code> 的 Last physical up/down time，可能光衰/协商不稳定</td></tr><tr><td>双工不匹配</td><td>两端固定千兆全双工，避免自动协商错乱</td></tr></tbody></table><h3 id="_7-4-运维黄金动作-软考-实操都适用" tabindex="-1"><a class="header-anchor" href="#_7-4-运维黄金动作-软考-实操都适用"><span>7.4 运维黄金动作（软考/实操都适用）</span></a></h3><ol><li><strong>每次变更前：<code>save</code> 备份 + 拍照（display current-configuration）</strong>；</li><li><strong>变更最小化</strong>，一条命令一条命令下，实时 <code>display</code> 验证；</li><li><strong>变更后观察</strong>：<code>display logbuffer</code>、<code>display alarm</code> 检查异常告警；</li><li>故障时先还原到最近的可用配置，再逐步验证。</li></ol><h2 id="_8-软考网络工程师相关考点提示" tabindex="-1"><a class="header-anchor" href="#_8-软考网络工程师相关考点提示"><span>8. 软考网络工程师相关考点提示</span></a></h2><p>网络工程师（中级）是很多电信运维人员考取的核心证书（每年下半年考试，案例题机考，满分 75、合格 45），与本篇内容强相关的考点：</p><table><thead><tr><th>考点</th><th>与本文对应内容</th><th>题型</th></tr></thead><tbody><tr><td>OSI/TCP-IP 与协议端口</td><td>初级篇 1 节</td><td>上午选择题</td></tr><tr><td>IP 子网划分计算</td><td>初级篇 2 节（必考计算）</td><td>选择题/案例</td></tr><tr><td>交换机 VLAN、trunk、VLANIF 互通</td><td>中级篇 1~2 节</td><td>案例大题</td></tr><tr><td>静态/默认路由、路由表理解</td><td>中级篇 3 节</td><td>案例大题</td></tr><tr><td>OSPF 单区域/多区域、邻居状态、DR</td><td>中级篇 4 节 / 本篇 1</td><td>案例大题</td></tr><tr><td>汇聚与链路聚合</td><td>中级篇 1 节</td><td>案例大题</td></tr><tr><td>ACL 基本/高级配置</td><td>中级篇 6 节</td><td>案例大题</td></tr><tr><td>DHCP 原理与配置、中继</td><td>中级篇 5 节</td><td>选择/案例</td></tr><tr><td>VRRP 冗余网关</td><td>本篇 3 节</td><td>案例大题</td></tr><tr><td>STP 生成树（环路防护）</td><td>本篇 7 节拓展</td><td>案例大题</td></tr><tr><td>SNMP/NTP/日志运维</td><td>本篇 5 节</td><td>选择/案例</td></tr><tr><td>网络设计三层架构</td><td>本篇 7 节</td><td>综合题</td></tr></tbody></table><p><strong>考前重点提醒</strong>：</p><ol><li><strong>route-policy/ACL 编号规则</strong>：基本 2000-2999、高级 3000-3999，RIP 30s/180s，OSPF 邻居建立报文顺序（Hello→DD→LSR→LSU→LSAck）；</li><li><strong>子网划分必须</strong>熟练（十进制-二进制互转）；</li><li><strong>命令拼写</strong>必须准确（如 <code>traffic-filter</code> 而非 <code>traffic-filte</code>），机考案例题命令拼错直接扣分；</li><li>结合大纲练习把 <code>display</code> 系列命令用熟（考试案例常给 <code>display</code> 输出让你分析）。</li></ol><h3 id="_8-1-软考案例题演练-示例" tabindex="-1"><a class="header-anchor" href="#_8-1-软考案例题演练-示例"><span>8.1 软考案例题演练（示例）</span></a></h3><p><strong>题目（改编）</strong>：某单位网络使用一台三层交换机 S1 连接两个 VLAN（VLAN 10 终端、VLAN 20 服务器），出口接路由器 R1 上互联网。要求：</p><ol><li>在 S1 上创建 VLAN 10、20，端口 G0/0/1 划入 VLAN 10；</li><li>配置 VLANIF 实现两网段互通（VLAN10=192.168.10.0/24，VLAN20=192.168.20.0/24）；</li><li>在 S1 配置默认路由指向 R1 互联地址 10.0.0.2；</li><li>拒绝 192.168.10.0/24 访问 192.168.20.0/24 中的 1.1.1.1 端口 80。</li></ol><p><strong>参考答案要点</strong>：</p><div class="language-vrp line-numbers-mode" data-highlighter="shiki" data-ext="vrp" style="--shiki-light:#0e1116;--shiki-dark:#f0f3f6;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0a0c10;"><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code"><code class="language-vrp"><span class="line"><span>[Huawei] vlan batch 10 20</span></span>
<span class="line"><span>[Huawei] interface GigabitEthernet0/0/1</span></span>
<span class="line"><span>[Huawei-GigabitEthernet0/0/1] port link-type access</span></span>
<span class="line"><span>[Huawei-GigabitEthernet0/0/1] port default vlan 10</span></span>
<span class="line"><span>[Huawei] interface Vlanif 10</span></span>
<span class="line"><span>[Huawei-Vlanif10] ip address 192.168.10.1 255.255.255.0</span></span>
<span class="line"><span>[Huawei] interface Vlanif 20</span></span>
<span class="line"><span>[Huawei-Vlanif20] ip address 192.168.20.1 255.255.255.0</span></span>
<span class="line"><span>[Huawei] ip route-static 0.0.0.0 0.0.0.0 10.0.0.2</span></span>
<span class="line"><span>[Huawei] acl number 3000</span></span>
<span class="line"><span>[Huawei-acl-adv-3000] rule 5 deny tcp source 192.168.10.0 0.0.0.255 destination 1.1.1.1 0 destination-port eq 80</span></span>
<span class="line"><span>[Huawei-acl-adv-3000] rule 10 permit ip</span></span>
<span class="line"><span>[Huawei-acl-adv-3000] quit</span></span>
<span class="line"><span>[Huawei] interface Vlanif 20</span></span>
<span class="line"><span>[Huawei-Vlanif20] traffic-filter inbound acl 3000</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>该类综合题覆盖&quot;VLAN + VLANIF + 静态路由 + 高级 ACL&quot;四件套，是软考下午案例的高概率组合。建议在 eNSP 上亲手搭建验证一遍。</p></blockquote><h2 id="_9-本篇小结" tabindex="-1"><a class="header-anchor" href="#_9-本篇小结"><span>9. 本篇小结</span></a></h2><table><thead><tr><th>主题</th><th>核心要点</th></tr></thead><tbody><tr><td>OSPF 进阶</td><td>多区域、Stub、DR/BDR 选举、汇总、下发默认路由</td></tr><tr><td>BGP</td><td>EBGP/IBGP、network 发布、display bgp peer 看 Established</td></tr><tr><td>VRRP</td><td>虚拟网关 + Master/Backup，终端网关写虚拟 IP</td></tr><tr><td>MPLS/VPN</td><td>PE/P/CE 模型，L3VPN 隔离客户路由</td></tr><tr><td>监控运维</td><td>SNMP、NTP、info-center 日志集中</td></tr><tr><td>工具</td><td>LLDP 邻居发现、eSight/iMaster NCE 网管</td></tr><tr><td>综合排障</td><td>三层架构、广播风暴/环路检测、变更备份</td></tr></tbody></table><h2 id="本节学习自测题" tabindex="-1"><a class="header-anchor" href="#本节学习自测题"><span>本节学习自测题</span></a></h2><ol><li>OSPF 多区域中，非骨干区域为什么必须连接 Area 0？Stub 区域的作用是什么？</li><li>DR/BDR 是怎么选出来的？为什么把优先级调到最大也不一定能当选？</li><li>写出两台交换机实现 VRRP 冗余网关的核心配置（虚拟 IP 192.168.50.254），并说明终端网关填什么地址。</li><li>BGP 邻居状态达 Established 的意义？邻居一直 Idle 可能是什么原因？</li><li>网络出现广播风暴如何定位？在华为接入交换机上写出开启环路检测并隔离异常端口的命令。</li></ol><blockquote><p>AI生成</p></blockquote>`,148)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};